const sections=Array.from(document.querySelectorAll(".page-section")),navigationLinks=Array.from(document.querySelectorAll(".nav-links a")),internalLinks=Array.from(document.querySelectorAll('a[href^="#"]')),experienceYears=document.getElementById("experience-years"),prefersReducedMotion=window.matchMedia("(prefers-reduced-motion: reduce)").matches,careerStartDate=new Date(2024,2),currentDate=new Date,totalMonths=12*(currentDate.getFullYear()-careerStartDate.getFullYear())+currentDate.getMonth()-careerStartDate.getMonth(),elapsedMonths=Math.max(totalMonths,0);function showView(e){const t=sections.find(t=>t.id===e);if(!t)return;sections.forEach(e=>{e.hidden=e!==t}),navigationLinks.forEach(t=>{t.getAttribute("href")===`#${e}`?t.setAttribute("aria-current","page"):t.removeAttribute("aria-current")});const r=t.querySelector("h1");document.title="home"===t.id?"Adarsh K. | Full Stack Developer - Fintech & Accessibility":`${r?r.textContent:"Portfolio"} | Adarsh K.`,t.scrollIntoView({behavior:prefersReducedMotion?"auto":"smooth",block:"start"})}experienceYears&&(experienceYears.textContent=`${Math.floor(elapsedMonths/12)} yrs ${elapsedMonths%12} mos`),internalLinks.forEach(e=>{e.addEventListener("click",t=>{t.preventDefault(),showView(e.getAttribute("href").slice(1))})}),showView("home");